using UnityEngine;using System.Collections;using System.IO;using System.Linq;
public class DetailPassReview:MonoBehaviour {
 string output="/Users/georgeambrose/Documents/Codex/2026-09-06/whqa/work/medical-detail-pass";string report="";WoodlandPlayer p;
 public static string Begin(){var g=new GameObject("Detail pass review");g.transform.SetParent(Object.FindFirstObjectByType<WoodlandPlayer>().transform,false);g.AddComponent<DetailPassReview>();return "Review running";}
 void Check(bool ok,string label){report+=(ok?"PASS ":"FAIL ")+label+"\n";File.WriteAllText(Path.Combine(output,"verification.txt"),report);}
 IEnumerator Shot(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(output,name+".png"));yield return new WaitForSeconds(.4f);}
 IEnumerator Start(){p=Object.FindFirstObjectByType<WoodlandPlayer>();p.inventory.persist=false;p.anatomy.ResetForCheckpoint();p.inventory.data.health=p.anatomy.condition;foreach(var h in Object.FindObjectsByType<WoodlandHostile>(FindObjectsSortMode.None))h.enabled=false;p.inventory.Find("suit").condition=100;p.inventory.Add("suit_patch",4);p.TeleportTo(new Vector3(-2,.12f,47),0);p.eye.transform.localPosition=new Vector3(0,1.65f,0);p.eye.transform.localRotation=Quaternion.identity;p.whiteHeadlight=true;p.torch.enabled=true;p.torch.intensity=10;p.torch.color=new Color(1,.95f,.85f);p.torch.spotAngle=52;p.torch.innerSpotAngle=30;p.battery=100;yield return new WaitForSeconds(1);
 Check(p.GetComponent<WoodlandMedicalWarning>().Active,"Hospital approach activates red watch warning");Check(p.torch.cookie!=null,"Headlamp uses soft reflector cookie");yield return Shot("exterior-review");
 bool opened=p.fieldKit.Toggle();Check(opened,"Backpack opens on clear ground");yield return new WaitForSeconds(1);Check(p.eye.transform.localPosition.y<.9f,"Backpack camera lowers to crouching height");Check(Object.FindObjectsByType<WoodlandPackItem>(FindObjectsSortMode.None).Length>=10,"Physical inventory props created");var item=Object.FindObjectsByType<WoodlandPackItem>(FindObjectsSortMode.None).FirstOrDefault();if(item){var col=item.GetComponent<Collider>();var ray=new Ray(p.eye.transform.position,col.bounds.center-p.eye.transform.position);bool selectable=Physics.Raycast(ray,out var hit,4)&&hit.collider.GetComponentInParent<WoodlandPackItem>();Check(selectable,"Visible inventory prop reachable by selection ray");p.fieldKit.SelectPhysical(item.id);}yield return Shot("backpack-review");p.fieldKit.Close();yield return new WaitForSeconds(1);
 p.anatomy.Hit(BodyRegion.LeftForearm,12,InjuryKind.Projectile,p.transform.position,Vector3.back);float bleeding=p.anatomy.Bleeding;Check(p.inventory.Find("suit").condition<100,"Projectile tears suit");int patches=p.inventory.Count("suit_patch");Check(p.equipment.UseSupply("suit_patch"),"Suit patch animation starts");yield return new WaitForSeconds(1.5f);yield return Shot("patch-review");yield return new WaitForSeconds(2);Check(p.inventory.Find("suit").condition==100&&p.inventory.Count("suit_patch")==patches-1,"Patch seals breach and consumes one patch");Check(p.anatomy.Bleeding>0,"Suit patch does not heal wound");p.anatomy.ResetForCheckpoint();
 var flow=Object.FindFirstObjectByType<WoodlandMedicalSequence>();flow.repair.Open();Check(!flow.repair.Connect(0,1),"Incorrect generator wire rejected");yield return Shot("generator-review");for(int n=0;n<3;n++)flow.repair.Connect(n,n);Check(flow.repair.SwitchOn(),"Correct wiring permits generator switch");yield return new WaitForSeconds(3);Check(flow.powered,"Generator restores power");flow.StartCoroutine(flow.Enter());yield return new WaitForSeconds(4);foreach(var h in Object.FindObjectsByType<WoodlandHostile>(FindObjectsSortMode.None))h.enabled=false;p.TeleportTo(new Vector3(200,.1f,29),0);p.cinematicLocked=true;p.eye.transform.position=new Vector3(200.7f,1.1f,29.3f);p.eye.transform.LookAt(new Vector3(199.6f,.3f,31));var crawl=Object.FindFirstObjectByType<MedicalCrawlingExile>();Check(crawl!=null,"Crawling exile exists");if(crawl){crawl.elapsed=0;crawl.stopped=false;yield return Shot("crawl-a");yield return new WaitForSeconds(.8f);yield return Shot("crawl-b");yield return new WaitForSeconds(.8f);yield return Shot("crawl-c");var bones=crawl.GetComponentsInChildren<Transform>();var hand=bones.First(t=>t.name=="mixamorig:LeftHand");Check(hand.position.y>.03f&&hand.position.y<.3f,"Crawling hand stays at floor height");}
 report+="Review captures are staged Unity runtime views; this is not a complete manual playthrough.\n";File.WriteAllText(Path.Combine(output,"verification.txt"),report);p.cinematicLocked=false;}
}
